cd /workspace && mkdir -p tmp && python3 submission/bridge.py < examples/scenario.json > tmp/out.json; python3 - <<'EOF'
import json
a=json.load(open('tmp/out.json'))
b=json.load(open('examples/expected.json'))
for k in ('streams','origins'):
    if a[k]!=b[k]:
        print("DIFF in",k)
        if k=='streams':
            for x,y in zip(a[k],b[k]):
                if x!=y: print("actual:",x,"\nexpect:",y)
        else:
            for label in b[k]:
                if a[k].get(label)!=b[k][label]:
                    print(label)
                    print(" actual:",a[k].get(label))
                    print(" expect:",b[k][label])
